class Solution {
long[] shortest(int start,int kind,List<List<long[]>> g){long[] d=new long[g.size()];Arrays.fill(d,Long.MAX_VALUE/4);d[start]=0;PriorityQueue<long[]> q=new PriorityQueue<>(Comparator.comparingLong(a->a[0]));q.add(new long[]{0,start});while(!q.isEmpty()){long[] p=q.remove();int u=(int)p[1];if(p[0]!=d[u])continue;for(long[] e:g.get(u)){int v=(int)e[0];long c=p[0]+e[kind];if(c<d[v]){d[v]=c;q.add(new long[]{c,v});}}}return d;}public int[] minCost(int n,int[] prices,int[][] roads){List<List<long[]>> g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new ArrayList<>());for(int[] r:roads){g.get(r[0]).add(new long[]{r[1],r[2],(long)r[2]*r[3]});g.get(r[1]).add(new long[]{r[0],r[2],(long)r[2]*r[3]});}int[] ans=prices.clone();for(int i=0;i<n;i++){long[] a=shortest(i,1,g),b=shortest(i,2,g);for(int j=0;j<n;j++)ans[i]=(int)Math.min(ans[i],prices[j]+a[j]+b[j]);}return ans;}
}
